var app = getApp()
var db = wx.cloud.database()
var commonUtil = require('../../utils/common-util.js')

Page({
  data: {
    activeTab: 'users',
    isAdmin: false,
    // 用户管理
    userList: [],
    searchKey: '',
    // 订单管理
    orderList: [],
    orderSearchKey: '',
    // 公告管理
    noticeTitle: '',
    noticeContent: '',
    noticeType: 'info',
    noticeDuration: 24,
    noticeList: [],
    // 帖子管理
    postList: [],
    postSearchKey: '',
    // 反馈管理
    feedbackList: [],
    feedbackFilter: '',
    complaintList: [],
    complaintFilter: '',
    // 系统通知
    notifyTarget: 'all',
    notifyUserPhone: '',
    notifyTitle: '',
    notifyContent: '',
    selectedNotifyTarget: null,
    selectedNotifyUserIds: [],
    notifyOrderSearch: '',
    notifyOrderList: [],
    // 客服管理
    serviceAccounts: [],
  },

  onLoad: function () {
    var userInfo = app.globalData.userInfo || {}
    try {
      var cached = wx.getStorageSync('userInfo')
      if (cached) userInfo = JSON.parse(cached)
    } catch (e) {}
    if (!userInfo.isAdmin && !userInfo.isManager) {
      wx.showToast({ title: '无权限访问', icon: 'none' })
      setTimeout(function () { wx.navigateBack() }, 1500)
      return
    }
    this.setData({ isAdmin: true })
    this._loadedTabs = {}
    this.loadTabData('users')
  },

  // === 标签切换 ===
  switchTab: function (e) {
    var tab = e.currentTarget.dataset.tab
    this.setData({ activeTab: tab })
    this.loadTabData(tab)
  },

  loadTabData: function (tab) {
    if (this._loadedTabs && this._loadedTabs[tab]) return
    this._loadedTabs = this._loadedTabs || {}
    this._loadedTabs[tab] = true
    switch (tab) {
      case 'users': this.loadUsers(); break
      case 'orders': this.loadOrders(); break
      case 'notice': this.loadNotices(); break
      case 'posts': this.loadPosts(); break
      case 'feedback': this.loadFeedbacks(); break
      case 'complaints': this.loadComplaints(); break
      case 'service': this.loadServiceAccounts(); break
      case 'notifications': break
    }
  },

  // === 用户管理 ===
  loadUsers: function () {
    var that = this
    var limit = 20
    wx.showLoading({ title: '加载中...', mask: true })
    db.collection('users').orderBy('createTime', 'desc').limit(limit).get({
      success: function (res) {
        wx.hideLoading()
        var colors = ['#0EA5E9', '#8B5CF6', '#F59E0B', '#10B981', '#EF4444', '#EC4899', '#6366F1', '#14B8A6']
        var list = res.data.map(function (u) {
          var hash = 0
          var name = u.nickName || '用户'
          for (var i = 0; i < name.length; i++) {
            hash = name.charCodeAt(i) + ((hash << 5) - hash)
          }
          u.avatarColor = colors[Math.abs(hash) % colors.length]
          if (u.isBanned) u.nickName = (u.nickName || '用户') + '(已封禁)'
          return u
        })
        that.setData({ userList: list })
      },
      fail: function () {
        wx.hideLoading()
        wx.showToast({ title: '加载失败，请重试', icon: 'none' })
      }
    })
  },

  bindSearchInput: function (e) {
    this.setData({ searchKey: e.detail.value })
  },

  searchUsers: function () {
    var that = this
    var key = that.data.searchKey.trim()
    if (!key) {
      that.loadUsers()
      return
    }
    var _ = db.command
    db.collection('users').where(_.or([
      { nickName: db.RegExp({ regexp: key, options: 'i' }) },
      { phone: key }
    ])).limit(20).get({
      success: function (res) {
        var colors = ['#0EA5E9', '#8B5CF6', '#F59E0B', '#10B981', '#EF4444', '#EC4899', '#6366F1', '#14B8A6']
        var list = res.data.map(function (u) {
          var hash = 0
          var name = u.nickName || '用户'
          for (var i = 0; i < name.length; i++) {
            hash = name.charCodeAt(i) + ((hash << 5) - hash)
          }
          u.avatarColor = colors[Math.abs(hash) % colors.length]
          return u
        })
        that.setData({ userList: list })
      }
    })
  },

  banUser: function (e) {
    var that = this
    var id = e.currentTarget.dataset.id
    var name = e.currentTarget.dataset.name
    wx.showModal({
      title: '确认封禁',
      content: '确定封禁用户 "' + name + '"？封禁后该用户无法发单和接单。',
      success: function (modal) {
        if (modal.confirm) {
          wx.cloud.callFunction({
            name: 'login',
            data: { action: 'banUser', userId: id },
            success: function (res) {
              if (res.result && res.result.code === 0) {
                wx.showToast({ title: '已封禁', icon: 'success' })
                that.loadUsers()
              } else {
                wx.showToast({ title: (res.result && res.result.msg) || '封禁失败', icon: 'none' })
              }
            },
            fail: function () {
              wx.showToast({ title: '封禁失败', icon: 'none' })
            }
          })
        }
      }
    })
  },

  unbanUser: function (e) {
    var that = this
    var id = e.currentTarget.dataset.id
    var name = e.currentTarget.dataset.name
    wx.showModal({
      title: '确认解封',
      content: '确定解封用户 "' + name + '"？解封后信誉分恢复为60分。',
      success: function (modal) {
        if (modal.confirm) {
          wx.cloud.callFunction({
            name: 'login',
            data: { action: 'unbanUser', userId: id },
            success: function (res) {
              if (res.result && res.result.code === 0) {
                wx.showToast({ title: '已解封', icon: 'success' })
                that.loadUsers()
              } else {
                wx.showToast({ title: (res.result && res.result.msg) || '解封失败', icon: 'none' })
              }
            },
            fail: function () {
              wx.showToast({ title: '解封失败', icon: 'none' })
            }
          })
        }
      }
    })
  },

  // === 订单管理 ===
  loadOrders: function () {
    var that = this
    db.collection('orders').orderBy('createTime', 'desc').limit(20).get({
      success: function (res) {
        var categoryMap = { water: '搬水', errand: '跑腿', substitute: '代课', secondhand: '二手', other: '其他' }
        var statusMap = { pending: '待接单', accepted: '进行中', delivering: '配送中', delivered: '待确认', paid: '已完成', completed: '已完成', cancelled: '已取消', expired: '已过期' }
        var list = res.data.map(function (o) {
          o.categoryText = categoryMap[o.category] || o.category || '其他'
          var statusVal = o.status
          if (typeof statusVal === 'object' && statusVal !== null) statusVal = statusVal.code || statusVal.status || JSON.stringify(statusVal)
          o.statusText = statusMap[statusVal] || (typeof statusVal === 'string' ? statusVal : '未知')
          o.createTimeText = commonUtil.formatDateTime(o.createTime)
          return o
        })
        that.setData({ orderList: list })
      }
    })
  },

  bindOrderSearchInput: function (e) {
    this.setData({ orderSearchKey: e.detail.value })
  },

  searchOrders: function () {
    var that = this
    var key = that.data.orderSearchKey.trim()
    if (!key) {
      that.loadOrders()
      return
    }
    var _ = db.command
    db.collection('orders').where(_.or([
      { orderNo: db.RegExp({ regexp: key, options: 'i' }) },
      { publisherName: db.RegExp({ regexp: key, options: 'i' }) },
      { publisherPhone: db.RegExp({ regexp: key, options: 'i' }) },
      { acceptorName: db.RegExp({ regexp: key, options: 'i' }) },
      { acceptorPhone: db.RegExp({ regexp: key, options: 'i' }) },
      { remark: db.RegExp({ regexp: key, options: 'i' }) }
    ])).limit(20).get({
      success: function (res) {
        var categoryMap = { water: '搬水', errand: '跑腿', substitute: '代课', secondhand: '二手', other: '其他' }
        var statusMap = { pending: '待接单', accepted: '进行中', delivering: '配送中', delivered: '待确认', paid: '已完成', completed: '已完成', cancelled: '已取消', expired: '已过期' }
        var list = res.data.map(function (o) {
          o.categoryText = categoryMap[o.category] || o.category || '其他'
          var statusVal = o.status
          if (typeof statusVal === 'object' && statusVal !== null) statusVal = statusVal.code || statusVal.status || JSON.stringify(statusVal)
          o.statusText = statusMap[statusVal] || (typeof statusVal === 'string' ? statusVal : '未知')
          o.createTimeText = commonUtil.formatDateTime(o.createTime)
          return o
        })
        that.setData({ orderList: list })
      }
    })
  },

  viewOrderDetail: function (e) {
    var id = e.currentTarget.dataset.id
    wx.navigateTo({ url: '/pages/order-detail/order-detail?id=' + id + '&from=admin' })
  },

  cancelOrder: function (e) {
    var that = this
    var id = e.currentTarget.dataset.id
    wx.showModal({
      title: '确认取消订单',
      content: '确定取消该订单？发布者和接单者将收到通知。',
      success: function (modal) {
        if (modal.confirm) {
          wx.cloud.callFunction({
            name: 'cancelOrder',
            data: { orderId: id, fromAdmin: true, reason: '管理员取消' },
            success: function (res) {
              var result = res.result
              if (result.code === 0) {
                wx.showToast({ title: '已取消', icon: 'success' })
                that.loadOrders()
              } else {
                wx.showToast({ title: result.msg || '取消失败', icon: 'none' })
              }
            },
            fail: function () {
              wx.showToast({ title: '取消失败', icon: 'none' })
            }
          })
        }
      }
    })
  },

  deductCredit: function (e) {
    var that = this
    var userId = e.currentTarget.dataset.userid
    var name = e.currentTarget.dataset.name || ''
    wx.showModal({
      title: '扣除信誉分',
      content: '确定扣除 ' + name + ' 的信誉分吗？请输入扣除分数（1-50分）：',
      editable: true,
      placeholderText: '请输入扣除分数',
      success: function (modal) {
        if (modal.confirm) {
          var score = parseInt(modal.content || '0')
          if (!score || score <= 0 || score > 50) {
            wx.showToast({ title: '请输入1-50的整数', icon: 'none' })
            return
          }
          wx.cloud.callFunction({
            name: 'login',
            data: { action: 'deductCredit', userId: userId, score: score },
            success: function (res) {
              if (res.result && res.result.code === 0) {
                wx.showToast({ title: '已扣除' + score + '分', icon: 'success' })
                that.loadOrders()
              } else {
                wx.showToast({ title: (res.result && res.result.msg) || '扣分失败', icon: 'none' })
              }
            },
            fail: function () { wx.showToast({ title: '扣分失败', icon: 'none' }) }
          })
        }
      }
    })
  },

  deleteOrder: function (e) {
    var that = this
    var id = e.currentTarget.dataset.id
    wx.showModal({
      title: '确认删除',
      content: '确定删除该订单？此操作不可恢复。',
      success: function (modal) {
        if (modal.confirm) {
          wx.cloud.callFunction({
            name: 'deleteOrder',
            data: { orderId: id },
            success: function (res) {
              var result = res.result
              if (result.code === 0) {
                wx.showToast({ title: '已删除', icon: 'success' })
                that.loadOrders()
              } else {
                wx.showToast({ title: result.msg || '删除失败', icon: 'none' })
              }
            },
            fail: function () {
              wx.showToast({ title: '删除失败', icon: 'none' })
            }
          })
        }
      }
    })
  },

  // === 公告管理 ===
  bindNoticeTitle: function (e) {
    this.setData({ noticeTitle: e.detail.value })
  },
  bindNoticeContent: function (e) {
    this.setData({ noticeContent: e.detail.value })
  },
  selectNoticeType: function (e) {
    this.setData({ noticeType: e.currentTarget.dataset.type })
  },
  selectDuration: function (e) {
    this.setData({ noticeDuration: parseInt(e.currentTarget.dataset.hours) })
  },

  publishNotice: function () {
    var that = this
    var content = that.data.noticeContent.trim()
    if (!content) { wx.showToast({ title: '请输入公告内容', icon: 'none' }); return }

    wx.showLoading({ title: '发布中' })
    wx.cloud.callFunction({
      name: 'login',
      data: {
        action: 'publishNotice',
        content: content,
        duration: that.data.noticeDuration,
        school: (app.globalData.userInfo && app.globalData.userInfo.school) || '',
        publisherRole: app.globalData.userInfo && app.globalData.userInfo.isAdmin ? 'admin' : (app.globalData.userInfo && app.globalData.userInfo.isManager ? 'manager' : 'admin')
      },
      success: function (res) {
        wx.hideLoading()
        if (res.result && res.result.code === 0) {
          wx.showToast({ title: '发布成功', icon: 'success' })
          that.setData({ noticeContent: '', noticeDuration: 24 })
          that.loadNotices()
        } else {
          wx.showToast({ title: (res.result && res.result.msg) || '发布失败', icon: 'none' })
        }
      },
      fail: function () {
        wx.hideLoading()
        wx.showToast({ title: '网络错误', icon: 'none' })
      }
    })
  },

  loadNotices: function () {
    var that = this
    var school = (app.globalData.userInfo && app.globalData.userInfo.school) || '广东江门中医药职业学院'
    db.collection('notices').where({ school: school }).orderBy('createTime', 'desc').limit(20).get({
      success: function (res) {
        var now = Date.now()
        var list = res.data.map(function (n) {
          var expireTime = n.expireTime ? new Date(n.expireTime).getTime() : 0
          n.isExpired = n.duration < 720 && expireTime > 0 && now > expireTime
          var durationText = n.duration >= 720 ? '永久' : n.duration >= 168 ? (n.duration / 24) + '天' : n.duration >= 24 ? (n.duration / 24) + '天' : n.duration + '小时'
          n.expireText = '持续' + durationText + (n.createTime ? ' · ' + commonUtil.formatDateTime(n.createTime) : '')
          return n
        })
        that.setData({ noticeList: list })
      }
    })
  },



  deleteNotice: function (e) {
    var that = this
    var id = e.currentTarget.dataset.id
    wx.showModal({
      title: '确认删除',
      content: '确定删除该公告？',
      success: function (modal) {
        if (modal.confirm) {
          wx.cloud.callFunction({
            name: 'login',
            data: { action: 'deleteNotice', _id: id },
            success: function (res) {
              if (res.result && res.result.code === 0) {
                wx.showToast({ title: '已删除', icon: 'success' })
                that.loadNotices()
              } else {
                wx.showToast({ title: '删除失败', icon: 'none' })
              }
            }
          })
        }
      }
    })
  },

  bindPostSearchInput: function (e) {
    this.setData({ postSearchKey: e.detail.value })
  },

  loadPosts: function () {
    var that = this
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'getPosts', page: 0, limit: 20 },
      success: function (res) {
        if (res.result && res.result.code === 0) {
          var list = (res.result.data || []).map(function (p) {
            p.createTimeText = commonUtil.formatDateTime(p.createTime)
            return p
          })
          that.setData({ postList: list })
        }
      }
    })
  },

  searchPosts: function () {
    var that = this
    var key = that.data.postSearchKey.trim()
    if (!key) { that.loadPosts(); return }
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'searchPosts', keyword: key },
      success: function (res) {
        if (res.result && res.result.code === 0) {
          var list = (res.result.data || []).map(function (p) {
            p.createTimeText = commonUtil.formatDateTime(p.createTime)
            return p
          })
          that.setData({ postList: list })
        }
      }
    })
  },

  viewPost: function (e) {
    wx.navigateTo({ url: '/pages/post-detail/post-detail?id=' + e.currentTarget.dataset.id + '&from=admin' })
  },

  deletePost: function (e) {
    var that = this
    wx.showModal({
      title: '确认删除',
      content: '确定删除该帖子？所有回复也将被删除',
      success: function (modal) {
        if (modal.confirm) {
          wx.cloud.callFunction({
            name: 'login',
            data: { action: 'deletePost', _id: e.currentTarget.dataset.id },
            success: function (res) {
              if (res.result && res.result.code === 0) {
                wx.showToast({ title: '已删除', icon: 'success' })
                that.loadPosts()
              }
            }
          })
        }
      }
    })
  },

  pinPost: function(e) {
    var that = this
    wx.showModal({
      title: '置顶帖子',
      content: '确定置顶该帖子？置顶后将在吐槽广场显示在最前面',
      success: function(modal) {
        if (modal.confirm) {
          wx.cloud.callFunction({
            name: 'login',
            data: { action: 'pinPost', _id: e.currentTarget.dataset.id },
            success: function(res) {
              if (res.result && res.result.code === 0) {
                wx.showToast({ title: '已置顶', icon: 'success' })
                that.loadPosts()
              }
            }
          })
        }
      }
    })
  },

  loadFeedbacks: function (status) {
    var that = this
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'getFeedbacks', status: status || that.data.feedbackFilter, school: (app.globalData.userInfo && app.globalData.userInfo.school) || '' },
      success: function (res) {
        if (res.result && res.result.code === 0) {
          var list = (res.result.data || []).map(function (f) {
            f.createTimeText = commonUtil.formatDateTime(f.createTime)
            return f
          })
          that.setData({ feedbackList: list })
        }
      }
    })
  },

  filterFeedback: function (e) {
    var status = e.currentTarget.dataset.status
    this.setData({ feedbackFilter: status })
    this.loadFeedbacks(status)
  },

  processFeedback: function (e) {
    var that = this
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'processFeedback', _id: e.currentTarget.dataset.id },
      success: function (res) {
        if (res.result && res.result.code === 0) {
          wx.showToast({ title: '已标记处理', icon: 'success' })
          that.loadFeedbacks()
        }
      }
    })
  },

  deleteFeedback: function (e) {
    var that = this
    wx.showModal({
      title: '确认删除',
      content: '确定删除该反馈？',
      success: function (modal) {
        if (modal.confirm) {
          wx.cloud.callFunction({
            name: 'login',
            data: { action: 'deleteFeedback', _id: e.currentTarget.dataset.id },
            success: function (res) {
              if (res.result && res.result.code === 0) {
                wx.showToast({ title: '已删除', icon: 'success' })
                that.loadFeedbacks()
              }
            }
          })
        }
      }
    })
  },

  exportFeedbacks: function () {
    var list = this.data.feedbackList
    if (!list || list.length === 0) {
      wx.showToast({ title: '暂无数据', icon: 'none' })
      return
    }
    var csv = '\uFEFF类型,内容,联系方式,状态,时间\n'
    for (var i = 0; i < list.length; i++) {
      var f = list[i]
      csv += '"' + (f.type || '') + '","' + (f.content || '').replace(/"/g, '""') + '","' + (f.contact || '') + '","' + (f.status === 'processed' ? '已处理' : '待处理') + '","' + (f.createTimeText || '') + '"\n'
    }
    wx.setClipboardData({
      data: csv,
      success: function () {
        wx.showToast({ title: '已复制到剪贴板，可粘贴到Excel', icon: 'none', duration: 3000 })
      }
    })
  },

  loadComplaints: function (status) {
    var that = this
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'getComplaints', status: status || that.data.complaintFilter, school: (app.globalData.userInfo && app.globalData.userInfo.school) || '' },
      success: function (res) {
        if (res.result && res.result.code === 0) {
          var list = (res.result.data || []).map(function (c) {
            c.createTimeText = commonUtil.formatDateTime(c.createTime)
            return c
          })
          that.setData({ complaintList: list })
        }
      }
    })
  },

  filterComplaint: function (e) {
    var status = e.currentTarget.dataset.status
    this.setData({ complaintFilter: status })
    this.loadComplaints(status)
  },

  showResolveOptions: function (e) {
    var id = e.currentTarget.dataset.id
    var that = this
    wx.showActionSheet({
      itemList: [
        '不扣分（仅警告）',
        '扣5分（轻微违规，如送达超时）',
        '扣10分（一般违规，如态度恶劣、虚假完成）',
        '扣20分（严重违规，如接单不送、手机号造假）',
        '自定义扣分'
      ],
      success: function (res) {
        var deductScore = 0
        if (res.tapIndex === 0) {
          that.doResolveComplaint(id, 0, '轻微问题，仅警告不扣分')
        } else if (res.tapIndex === 1) {
          that.doResolveComplaint(id, 5, '轻微违规')
        } else if (res.tapIndex === 2) {
          that.doResolveComplaint(id, 10, '一般违规')
        } else if (res.tapIndex === 3) {
          that.doResolveComplaint(id, 20, '严重违规')
        } else if (res.tapIndex === 4) {
          // 自定义扣分
          wx.showModal({
            title: '自定义扣分',
            editable: true,
            placeholderText: '请输入1-50的扣分分数',
            success: function (modal) {
              if (modal.confirm) {
                var score = parseInt(modal.content || '0')
                if (!score || score <= 0 || score > 50) {
                  wx.showToast({ title: '请输入1-50的整数', icon: 'none' })
                  return
                }
                that.doResolveComplaint(id, score, '自定义扣分')
              }
            }
          })
        }
      }
    })
  },

  doResolveComplaint: function (id, deductScore, note) {
    var that = this
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'resolveComplaint', _id: id, deductScore: deductScore, resolveNote: note || '' },
      success: function (res) {
        if (res.result && res.result.code === 0) {
          var msg = deductScore > 0 ? '已处理并扣' + deductScore + '分' : '已标记处理'
          wx.showToast({ title: msg, icon: 'success' })
          that.loadComplaints()
        }
      }
    })
  },

  deleteComplaint: function (e) {
    var that = this
    wx.showModal({
      title: '确认删除',
      content: '确定删除该投诉？',
      success: function (modal) {
        if (modal.confirm) {
          wx.cloud.callFunction({
            name: 'login',
            data: { action: 'deleteComplaint', _id: e.currentTarget.dataset.id },
            success: function (res) {
              if (res.result && res.result.code === 0) {
                wx.showToast({ title: '已删除', icon: 'success' })
                that.loadComplaints()
              }
            }
          })
        }
      }
    })
  },

  exportComplaints: function () {
    var list = this.data.complaintList
    if (!list || list.length === 0) {
      wx.showToast({ title: '暂无数据', icon: 'none' })
      return
    }
    var csv = '\uFEFF投诉对象,原因,内容,投诉者,联系方式,订单号,状态,时间\n'
    for (var i = 0; i < list.length; i++) {
      var c = list[i]
      csv += '"' + (c.targetUserName || '') + '","' + (c.complaintType || '') + '","' + (c.content || '').replace(/"/g, '""') + '","' + (c.complainantName || '') + '","' + (c.complainantPhone || '') + '","' + (c.orderNo || '') + '","' + (c.status === 'resolved' ? '已处理' : '待处理') + '","' + (c.createTimeText || '') + '"\n'
    }
    wx.setClipboardData({
      data: csv,
      success: function () {
        wx.showToast({ title: '已复制到剪贴板，可粘贴到Excel', icon: 'none', duration: 3000 })
      }
    })
  },

  setNotifyTarget: function (e) {
    var target = e.currentTarget.dataset.target
    this.setData({ notifyTarget: target, selectedNotifyTarget: null, selectedNotifyUserIds: [] })
    // 切换到投诉/反馈时加载对应列表
    if (target === 'complaint') {
      this.loadComplaints()
    } else if (target === 'feedback') {
      this.loadFeedbacks()
    } else if (target === 'order') {
      this.setData({ notifyOrderList: [] })
    }
  },

  selectNotifyTarget: function (e) {
    var index = e.currentTarget.dataset.index
    var target = this.data.notifyTarget
    var userIds = []
    if (target === 'complaint') {
      var item = this.data.complaintList[index]
      if (item) userIds = [item._openid, item.targetUserId].filter(function(id) { return !!id })
    } else if (target === 'feedback') {
      var item2 = this.data.feedbackList[index]
      if (item2) userIds = [item2._openid].filter(function(id) { return !!id })
    } else if (target === 'order') {
      var item3 = this.data.notifyOrderList[index]
      if (item3) userIds = [item3.publisherId, item3.acceptorId].filter(function(id) { return !!id })
    }
    this.setData({ selectedNotifyTarget: index, selectedNotifyUserIds: userIds })
  },

  bindNotifyOrderSearch: function (e) {
    this.setData({ notifyOrderSearch: e.detail.value })
  },

  searchNotifyOrder: function () {
    var that = this
    var keyword = that.data.notifyOrderSearch.trim()
    if (!keyword) return
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'searchOrders', keyword: keyword },
      success: function (res) {
        if (res.result && res.result.code === 0) {
          that.setData({ notifyOrderList: res.result.data || [] })
        }
      }
    })
  },

  bindNotifyTitle: function (e) {
    this.setData({ notifyTitle: e.detail.value })
  },

  bindNotifyContent: function (e) {
    this.setData({ notifyContent: e.detail.value })
  },

  sendNotification: function () {
    var that = this
    var title = that.data.notifyTitle.trim()
    var content = that.data.notifyContent.trim()
    if (!title || !content) {
      wx.showToast({ title: '标题和内容不能为空', icon: 'none' })
      return
    }
    var data = {
      action: 'sendSystemNotification',
      title: title,
      content: content,
      targetType: that.data.notifyTarget === 'all' ? 'all' : 'users',
      targetUserIds: that.data.selectedNotifyUserIds
    }
    wx.showLoading({ title: '发送中' })
    wx.cloud.callFunction({
      name: 'login',
      data: data,
      success: function (res) {
        wx.hideLoading()
        if (res.result && res.result.code === 0) {
          wx.showToast({ title: res.result.msg || '发送成功', icon: 'success' })
          that.setData({ notifyTitle: '', notifyContent: '', selectedNotifyTarget: null, selectedNotifyUserIds: [] })
        } else {
          wx.showToast({ title: (res.result && res.result.msg) || '发送失败', icon: 'none' })
        }
      },
      fail: function () { wx.hideLoading(); wx.showToast({ title: '网络错误', icon: 'none' }) }
    })
  },

  loadServiceAccounts: function () {
    var that = this
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'getServiceAccounts' },
      success: function (res) {
        if (res.result && res.result.code === 0) {
          that.setData({ serviceAccounts: res.result.data || [] })
        }
      }
    })
  },

  addService: function () {
    var accounts = this.data.serviceAccounts.concat([''])
    this.setData({ serviceAccounts: accounts })
  },

  removeService: function (e) {
    var index = e.currentTarget.dataset.index
    var accounts = this.data.serviceAccounts
    accounts.splice(index, 1)
    this.setData({ serviceAccounts: accounts })
  },

  bindServiceInput: function (e) {
    var index = e.currentTarget.dataset.index
    var accounts = this.data.serviceAccounts
    accounts[index] = e.detail.value
    this.setData({ serviceAccounts: accounts })
  },

  saveServiceAccounts: function () {
    var that = this
    var validAccounts = that.data.serviceAccounts.filter(function (a) { return a && a.trim() })
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'saveServiceAccounts', accounts: validAccounts },
      success: function (res) {
        if (res.result && res.result.code === 0) {
          wx.showToast({ title: '保存成功', icon: 'success' })
          that.setData({ serviceAccounts: validAccounts })
        } else {
          wx.showToast({ title: (res.result && res.result.msg) || '保存失败', icon: 'none' })
        }
      }
    })
  }
})
